(()=>{"use strict";
const $=id=>document.getElementById(id),state={sync:"idle",lastSync:null,session:"unknown",remote:"unknown"};let forcing=false;
function setText(id,value){const el=$(id);if(el)el.textContent=value}
function render(){const online=navigator.onLine;let label="Connecté",detail="Connecté au réseau",cls="is-online";
if(!online){label="Hors ligne";detail="Données conservées sur cet appareil";cls="is-offline"}else if(state.session==="expired"){label="Session à vérifier";detail="Le serveur BEP ne confirme pas la session";cls="is-error"}else if(state.sync==="conflict"){label="Synchronisation suspendue";detail="Conflit détecté : données locales préservées";cls="is-error"}else if(state.sync==="pending"){label="Synchronisation en attente";detail="Modifications locales à transmettre";cls="is-pending"}else if(state.sync==="syncing"){label="Synchronisation…";detail="Vérification et récupération des données auprès du serveur";cls="is-pending"}
const root=$("bepConnectionStatus");if(root){root.className="bep-connection-status "+cls;root.title=detail}setText("bepConnectionLabel",label);setText("settingsNetworkState",online?"Connecté":"Hors ligne");
setText("settingsSessionState",state.session==="expired"?"Session non confirmée":state.session==="active"?"Session confirmée par le serveur":window.bepSignedIn?"Session locale — vérification nécessaire":"Non connecté / mode local");
const fresh=state.lastSync&&Date.now()-new Date(state.lastSync).getTime()<900000;
setText("settingsSyncState",state.sync==="conflict"?"Suspendue — conflit à résoudre":state.sync==="pending"?"En attente":state.sync==="syncing"?"En cours":state.remote==="error"?"Échec de la dernière vérification":fresh?"Données vérifiées récemment":state.lastSync?"Vérification ancienne — actualisation nécessaire":"Aucune synchronisation confirmée sur cet appareil");
setText("settingsLastSync",state.lastSync?new Date(state.lastSync).toLocaleString("fr-FR"):"Aucune synchronisation confirmée sur cet appareil");
const button=$("forceSyncBtn");if(button){button.disabled=forcing||!online;button.textContent=forcing?"Synchronisation en cours…":"Forcer la synchronisation"}}
async function refreshPending(){try{const p=await window.BEPOffline?.readPending?.();const count=p?1:0;setText("settingsPendingCount",String(count));if(count&&state.sync==="idle")state.sync="pending";if(!count&&state.sync==="pending")state.sync="idle"}catch{setText("settingsPendingCount","Indisponible")}render()}
function showReauthentication(reason){const gate=$("authGate"),app=document.querySelector(".app"),message=$("authMessage");if(message)message.textContent=reason||"La session BEP doit être rétablie. Reconnecte-toi pour accéder aux données du compte.";if(gate)gate.hidden=false;if(app)app.setAttribute("aria-hidden","true")}
async function checkSession(){if(!navigator.onLine||!window.bepSignedIn)return;try{const api=(window.BEP_API_BASE||"https://bep-v2-api.onrender.com").replace(/\/+$/,""),r=await fetch(api+"/api/auth/status",{credentials:"include",cache:"no-store"});if(r.status===401){state.session="expired";state.remote="error";window.bepSignedIn=false;showReauthentication();render();return}if(!r.ok){state.remote="error";render();return}const auth=await r.json();if(!auth.user){state.session="expired";state.remote="error";window.bepSignedIn=false;showReauthentication("Cette session a été fermée car ton compte a été connecté sur un autre appareil. Reconnecte-toi pour continuer.");render();return}state.session="active"}catch{state.remote="error"}render()}
async function forceSync(){const feedback=$("forceSyncFeedback");if(forcing)return;forcing=true;state.sync="syncing";state.remote="unknown";if(feedback)feedback.textContent="Vérification de la session et récupération des données du compte…";render();try{if(!window.BEPOffline?.forceSync)throw Error("Le module de synchronisation BEP n'est pas disponible. Actualise l'application.");const result=await window.BEPOffline.forceSync();state.session="active";state.remote="fresh";state.sync="idle";state.lastSync=result.verifiedAt;if(feedback)feedback.textContent="Synchronisation terminée. Les données du compte ont été récupérées et vérifiées.";window.dispatchEvent(new Event("bep:auth-ready"));await refreshPending()}catch(error){state.sync=error.message.includes("conflit")||error.message.includes("diffèrent")?"conflict":"idle";if(error.message.includes("session")||error.message.includes("Reconnecte")){state.session="expired";showReauthentication()}state.remote="error";if(feedback)feedback.textContent=error.message||"La synchronisation a échoué. Les données locales sont conservées."}finally{forcing=false;render()}}
window.addEventListener("online",async()=>{render();await checkSession();await refreshPending()});window.addEventListener("offline",render);window.addEventListener("bep:offline-pending",()=>{state.sync="pending";refreshPending()});window.addEventListener("bep:offline-conflict",()=>{state.sync="conflict";render()});window.addEventListener("bep:offline-sync-error",()=>{state.sync="pending";render()});
window.addEventListener("bep:offline-synced",event=>{state.sync="idle";state.lastSync=event.detail?.verifiedAt||new Date().toISOString();state.remote="fresh";try{localStorage.setItem("bep-last-sync-at",state.lastSync)}catch{}refreshPending()});
window.addEventListener("bep:auth-ready",()=>{if(window.bepSignedIn){state.session="active";state.sync="idle";checkSession()}render();refreshPending()});$("forceSyncBtn")?.addEventListener("click",forceSync);try{state.lastSync=localStorage.getItem("bep-last-sync-at")}catch{}render();refreshPending();checkSession();window.setInterval(checkSession,15000);window.setInterval(refreshPending,10000);
})();